@POST
@Path("{dispositivo}/v2/pedido/{numeroReferencia}/validar/biometria/instalacao")
@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
@DispositivoSeguro
@Cors(enable = false)
public Response validarBiometriasFaciaisParaInstalar(@Context HttpServletRequest httpRequest,
		@PathParam("dispositivo") Long dispositivoId, @PathParam("numeroReferencia") final Long numeroReferencia,
		@Valid ValidacaoBiometriasFaciaisDTO validacaoBiometriasFaciais) {

	// Obtem os metadados de Liveness dos headers HTTP
	Map<String, String> livenessHttpHeadersMap = HttpUtil.getLivenessHttpHeadersMap(httpRequest);
	// adiciona aos já enviados se já existir
	if (validacaoBiometriasFaciais.metadadosLiveness == null) {
		validacaoBiometriasFaciais.metadadosLiveness = new HashMap<>();
	}
	validacaoBiometriasFaciais.metadadosLiveness.putAll(livenessHttpHeadersMap);

	// Obtem headers para validação
	String soMobile = httpRequest.getHeader(X_APP_SO_HEADER);
	String appError = httpRequest.getHeader(APP_ERROR_HEADER);

	String jwtBiometria = this.certificadoBC.validarBiometriasFaciaisParaInstalar(numeroReferencia, dispositivoId,
			validacaoBiometriasFaciais, soMobile, appError);
	Map<String, String> map = new HashMap<>();
	map.put("jwt", jwtBiometria);
	return Response.ok(map).build();
}

