@POST
@Path("{dispositivo}/pedido/{numeroReferencia}/pre-instalacao-certificado")
@Produces("application/json")
@Cors(enable = false)
@DispositivoSeguro
@Transactional
public Response preEmissaoCredencialInstalacao(@PathParam("dispositivo") Long dispositivoId,
		@Valid PreEmissaoComCredencialInstalacaoDTO emissao) { // valida dados de
	// acesso do SCDS e se o pedido não se encontra pendente
	SCDSCertReqStatus statusPedido = certificadoBC.obterStatusPedidoSCDSExcecaoCasoPendente(
			emissao.numeroReferencia, new JwtTokenScdsUserCredential(emissao.credencialInstalacao));

	Certificado certificado = certificadoBC.recuperarCertificado(emissao.numeroReferencia);
	String pdfTermoDigital = null;

	if (statusPedido.isCertificadoGerado()) {
		if (certificado == null) {
			throw new SmartCertException(Message.ESTADO_INSTALACAO_ILEGAL);
		}
	} else {
		boolean termoDigitalNecessario = certificadoBC.isTermoDigitalNecessario(emissao.numeroReferencia);

		if (termoDigitalNecessario && (certificado == null || certificado.isEnvioTermoPendente())) {
			pdfTermoDigital = certificadoBC.obterTermoDigital(emissao.numeroReferencia).getPdf();
		}
	}

	return Response.ok(new PreEmissaoResponseDTO(certificado, pdfTermoDigital)).build();
}

