@POST
@Path("{dispositivo}/pedido/{numeroReferencia}/instalar-certificado")
@Produces("application/json")
@Cors(enable = false)
@DispositivoSeguro
public Response emitirCertificadoComCredencialInstalacao(@PathParam("dispositivo") Long dispositivoId,
		@Context HttpServletRequest httpRequest, @Valid EmissaoCredencialInstalacaoDTO emissao) {

	// obtem status do pedido, exceção caso pendente
	SCDSCertReqStatus statusPedido = certificadoBC
			.obterStatusPedidoSCDSExcecaoCasoPendente(emissao.getNumeroReferencia(), emissao.getCredential());

	// obtem certificado ou cadastra se ainda não existir no NeoID
	// TODO - Sobe algum tipo de erro caso ocorra erro de Constraint devido a Unique
	// ? Ou deixa estourar Erro Interno?
	Certificado certificado = certificadoBC.obtemCertificadoOuCriaPendente(emissao);

	// inicia o processo de emissão
	Instalacao instalacao = certificadoBC.emitir(dispositivoId, emissao, statusPedido, certificado,
			HttpUtil.getClientIp(httpRequest));

	CertificadoDTO.Mobile dto = CertificadoDTO.criarMobileDTO(instalacao, true);
	return Response.ok(dto).build();
}

