private void validateMetadata(InputPart metadataPart) throws IOException {

	String contentType = metadataPart.getHeaders().getFirst("Content-Type");
	if (contentType == null || !contentType.contains("application/json")) {
		throw new SmartCertException(ASSINATURA_PDF_METADATA_APENAS_JSON);
	}

	String json = metadataPart.getBody(String.class, null);

	if (json == null || json.trim().isEmpty()) {
		throw new SmartCertException(ASSINATURA_PDF_METADATA_OBRIGATORIO);
	}
}

@POST
@Path("{dispositivo}/access-token-sem-expiracao")
@Produces("application/json")
@Cors(enable = false)
@DispositivoSeguro
@Transactional
public Response obterAccessTokenSemExpiracao(@PathParam("dispositivo") Long dispositivoId, DesafioPinDTO dto) {
	Instalacao instalacao = this.instalacaoBC.find(dto.instalacao);

	if (instalacao == null) {
		throw new SmartCertException(Message.INSTALACAO_NAO_ENCONTRADA);
	}

	if (instalacao.getDispositivo().getId().compareTo(dispositivoId) != 0) {
		throw new SmartCertException(Message.DISPOSITIVO_INSTALACAO_INVALIDA);
	}

	if (dto.pin == null) {
		throw new SmartCertException(Message.INVALID_PIN);
	}

	if (dto.desafio == null || !OTPOnLineUtil.getOTPWithKey(dto.pin, instalacao.getChave()).equals(dto.desafio)) {
		throw new SmartCertException(Message.OTP_ONLINE_INVALIDO);
	}

	pinResolver.authenticateByPin(instalacao.getCertificado(), dto.pin);

	instalacao.setAccessToken(OTPOffLineUtil.generateKeySha256());

	AccessTokenDTO accessTokenDTO = new AccessTokenDTO();
	accessTokenDTO.accessToken = cipher.encrypt(instalacao.getAccessToken());

	return Response.ok(accessTokenDTO).build();
}

