@PUT
@Path("{dispositivo}/atualizar-cadastro-legado")
@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
@Cors(enable = false)
@Transactional
public Response atualizarCadastroLegado(@PathParam("dispositivo") Long dispositivoId,
		@Valid CadastroLegadoDTO dto) {
	Dispositivo dispositivo = dispositivoBC.find(dispositivoId);

	if (dispositivo == null) {
		throw new SmartCertException(Message.DISPOSITIVO_NOT_FOUND);
	}

	if (!dispositivo.getStatus().isNaoRegistrado()) {
		throw new SmartCertException(Message.CREDENCIAL_DISPOSITIVO_PARAM_IDENTIFICACAO_INVALIDO);
	}

	if (dispositivo.getPushId() != null && !dispositivo.getPushId().equals(dto.pushId)) {
		throw new SmartCertException(Message.CREDENCIAL_DISPOSITIVO_PARAM_IDENTIFICACAO_INVALIDO);
	}

	// validar token sem considerar a validade
	// TODO - rever, se tem a chance do token nao estiver persistido no mobile,
	// retirar do DTO e não verificar
	if (!JWTDispositivoUtil.verifyTokenLegado(dto.token, String.valueOf(dispositivoId), false)) {
		throw new SmartCertException(Message.CREDENCIAL_DISPOSITIVO_PARAM_IDENTIFICACAO_INVALIDO);
	}

	// valida o identificador público
	dispositivoBC.validarIdentificadorPublico(dto.identificadorPublico);

	// valida a plataforma
	dispositivoBC.validarPlataforma(dto.plataforma);

	dispositivoBC.atualizarCadastroLegado(dispositivo, dto);

	Map<String, Object> mapResponse = new HashMap<>();
	mapResponse.put("atestadoAte", dispositivo.getAtestadoAte());

	return Response.ok(mapResponse).build();
}

