@POST
@Path("{dispositivo}/checagem-pin")
@Produces("application/json")
@Cors(enable = false)
@DispositivoSeguro
@Transactional
public Response checagemPin(@PathParam("dispositivo") Long dispositivoId, DesafioPinDTO dto) {
	Instalacao instalacao = this.instalacaoBC.find(dto.instalacao);

	if (instalacao == null) {
		throw new SmartCertException(Message.INSTALACAO_NAO_ENCONTRADA);
	}

	if (instalacao.getDispositivo().getId().compareTo(dispositivoId) != 0) {
		throw new SmartCertException(Message.DISPOSITIVO_INSTALACAO_INVALIDA);
	}

	if (dto.pin == null) {
		throw new SmartCertException(Message.INVALID_PIN);
	}

	if (dto.desafio == null || !OTPOnLineUtil.getOTPWithKey(dto.pin, instalacao.getChave()).equals(dto.desafio)) {
		throw new SmartCertException(Message.OTP_ONLINE_INVALIDO);
	}

	Certificado certificado = instalacao.getCertificado();
	// já migrou para o modelo novo ?
	boolean modeloNovoAutenticacao = StringUtils.isNotBlank(certificado.getChaveAcessoParticao());

	if (modeloNovoAutenticacao) {
		pinResolver.authenticateByPin(certificado, dto.pin);
	} else {
		if (!cryptoAPI.validarExistenciaChaveMobile(certificado.getNamespace(), CredentialType.PIN, dto.pin)) {
			throw new SmartCertException(Message.VERIFY_OWNER_KEY_NOT_PRESENT);
		}
	}

	// se modelo antigo, vai migrar para o modelo novo
	if (!modeloNovoAutenticacao) {
		certificado.setChaveAcesso(gerarChaveAcesso(dto.pin));
		certificado.setChaveAcessoParticao(gerarChaveAcessoParticao(dto.pin));
	}

	// instalação com checagem realizada
	instalacao.setChecagemPinNecessaria(false);

	return Response.ok().build();
}

