@Path("atualizacao-serproid-desktop")
public class AtualizacaoSerproIDDesktopREST {

	private static final Logger LOGGER = Logger.getLogger(AtualizacaoSerproIDDesktopREST.class);

	@Inject
	private CertificadoDAO certificadoDAO;

	@POST
	@Path("enviar-emails")
	public Response enviarEmails(@HeaderParam("Authorization") String password) {

		if (password == null || !password.equals("fdsuy3654fdurty650453uq5r103947urfnDaf5416*-+99=+")) {
			return Response.status(Status.FORBIDDEN).build();
		}

		ExecutorService executor = Executors.newSingleThreadExecutor();

		executor.execute(() -> {
			List<String> emails = certificadoDAO.getEmailsCertificadosAtivosQueJaForamPareadosEmMaquinas();

			LOGGER.info("Quantidade de e-mails: " + emails.size());

			List<String> emailsComFalha = new ArrayList<>();

			int countEnviados = 0;

			for (int i = 0; i < emails.size(); i++) {
				String email = emails.get(i);

				try {
					EnvioEmailUtil.enviarAtualizacaoSerproIDDesktop(email);
					countEnviados++;
				} catch (Exception e) {
					emailsComFalha.add(email);
					LOGGER.error("Falha ao enviar email para " + email);
				}

				LOGGER.info("Enviado email atualização para: " + email);

				if (i % 20 == 0) {
					LOGGER.info("Solicitações de envio: " + i + 1 + " de " + emails.size());
					try {
						Thread.sleep(1000);
					} catch (InterruptedException e) {
						LOGGER.error("Falha ao aguardar após o envio do email: " + email);
					}
				}
			}

			LOGGER.info("Quantidade de envios com falha: " + emailsComFalha.size());
			for (String emailComFalha : emailsComFalha) {
				LOGGER.info("Email com falha: " + emailComFalha);

			}

			LOGGER.info("Concluído! \nTotal de emails enviados com sucesso: " + countEnviados);
		});

		return Response.ok("Executando...").build();

	}

}

