@GET
@Path("solicitacao/autenticacao/{id_solicitacao}/status")
@Produces("application/json")
@CacheControl(value = "max-age=0")
@Transactional
@ApiOperation(value = "Verificar status da solicitação de autenticação", tags={"autenticacao"}, response=RespostaStatusAutenticacaoDTO.class)
@ApiResponses(value = {
		@ApiResponse(code = 404, message = "Solicitação de autenticação não encontrada"),
		@ApiResponse(code = 403, message = "Credencial apresentada não possui permissão para a operação")
		})
@Cors(enable = true)
public RespostaStatusAutenticacaoDTO verificarStatusDaAutenticacao(
		@PathParam("id_solicitacao") @NotNull(message="O identificador da solicitação é obrigatório")
		@ApiParam(name="id_solicitacao", value="Id da Solicitação", required=true) Long idSolicitacao,
		@Context HttpServletRequest request) {

	final SolicitacaoAutenticacao solicitacao = bc.obterSolicitacaoAutenticacao(idSolicitacao);
	if(solicitacao == null) {
		throw new SmartCertException(Message.SOLICITACAO_AUTENTICACAO_NOT_FOUND);
	}

	Aplicativo app = getAplicativo(request);
	if(! app.getId().equals(solicitacao.getAplicativo().getId())){
		throw new SmartCertException(Message.CREDENCIAL_SEM_PERMISSAO);
	}

	RespostaStatusAutenticacaoDTO response = new RespostaStatusAutenticacaoDTO();
	response.id = solicitacao.getId();
	response.data_envio = solicitacao.getDataSolicitacao();
	response.data_validade = solicitacao.getDataValidade();
	response.status = solicitacao.getStatus().name();
	response.data_resposta = solicitacao.getDataResposta();
	response.ip_dispositivo_resposta = solicitacao.getIpRespondente();

	if( solicitacao.isStatusAceito() ){
		response.certificado_pem = solicitacao.getCertificado().getCertificadoB64();
	} else if( solicitacao.isStatusExpirado() ) {
		response.status = SolicitacaoAutenticacao.Status.EXPIRADO.name();
	}

	return response;
}

