@GET
@Path("solicitacao/assinatura/{id_solicitacao}/status")
@Produces("application/json")
@CacheControl(value = "max-age=0")
@Transactional
@ApiOperation(value = "Verificar status da solicitação de assinatura digital",tags={"assinatura"}, response = RespostaStatusAssinaturaDTO.class)
@ApiResponses(value = {
		@ApiResponse(code = 404, message = "Solicitação de assinatura não encontrada"),
		@ApiResponse(code = 403, message = "Credencial apresentada não possui permissão para a operação")
		})
@Cors(enable = true)
public Response verificarStatusDaAssinatura(
		@PathParam("id_solicitacao") @NotNull(message="O identificador da solicitação é obrigatório")
		@ApiParam(name="id_solicitacao", value="Id da Solicitação", required=true) Long idSolicitacao,
		@Context HttpServletRequest request) {

	final SolicitacaoAssinatura solicitacao = bc.obterSolicitacaoAssinatura(idSolicitacao);
	if(solicitacao == null) {
		throw new SmartCertException(Message.SOLICITACAO_ASSINATURA_NOT_FOUND);
	}

	Aplicativo app = getAplicativo(request);
	if(! app.getId().equals(solicitacao.getAplicativo().getId())){
		throw new SmartCertException(Message.CREDENCIAL_SEM_PERMISSAO);
	}

	RespostaStatusAssinaturaDTO response = new RespostaStatusAssinaturaDTO();
	response.id = solicitacao.getId();
	response.data_envio = solicitacao.getDataSolicitacao();
	response.data_validade = solicitacao.getDataValidade();
	response.status = solicitacao.getStatus().name();
	response.data_resposta = solicitacao.getDataResposta();
	response.ip_dispositivo_resposta = solicitacao.getIpRespondente();

	if( solicitacao.isStatusAceito() ){
		response.certificado_pem = solicitacao.getCertificado().getCertificadoB64();
		for(Assinatura assinatura: solicitacao.getAssinaturas()){
			response.assinaturas.add(new RespostaAssinaturaDTO(assinatura.getHashBase64(), assinatura.getAssinatura()));
		}
	} else if( solicitacao.isStatusExpirado() ) {
		response.status = SolicitacaoAssinatura.Status.EXPIRADO.name();
	}

	return Response.ok(response).build();
}

private Aplicativo getAplicativo(HttpServletRequest req) {
	return (Aplicativo)req.getAttribute("aplicativo");
}

