@POST
@Path("login-otp")
@Consumes(MediaType.APPLICATION_FORM_URLENCODED)
@Produces(MediaType.APPLICATION_JSON)
@Cors(enable = false)
@ChecaCSRF
@IPExtractor
@Transactional
public Response loginOtp(@FormParam("otp") final String codigoAcesso, @FormParam("captcha") final String captcha,
		@HeaderParam("x-token-auth") final String tokenAuth) {

	if (!HCaptchaVerifier.verify(captcha)) {
		throw new SmartCertException(Message.REQUISICAO_OAUTH_INVALIDA);
	}

	final AuthorizationRequest authRequest = authRequestBC.obterPorAuthState(tokenAuth);
	if (authRequest == null) {
		throw new SmartCertException(Message.REQUISICAO_OAUTH_INVALIDA);
	}

	final Instalacao inst = instalacaoBC.find(obterIdInstalacao(codigoAcesso));
	if (inst == null) {
		throw new SmartCertException(Message.INSTALACAO_NAO_ENCONTRADA);
	}

	if (authRequest.isStatusPrimeiroFatorApresentado()) {
		return Response.ok(RespostaAuthorizeBuilder.loginOtp(inst)).build();
	}

	if (!authRequest.isStatusIniciado()) {
		throw new SmartCertException(Message.REQUISICAO_SUSPEITA);
	}

	if (authRequest.isStatusIniciado() && authRequest.isExpiradoAposIniciado()) {
		throw new SmartCertException(Message.VALIDADE_AUTHORIZE_EXPIRADA);
	}

	if (authRequest.getLoginHint() != null && !inst.getCertificado().getNi().equals(authRequest.getLoginHint())) {
		throw new SmartCertException(Message.OAUTH_CERTIFICADO_NI_INVALIDO, authRequest.getLoginHint());
	}

	String chaveOtp = inst.getChave();
	if (Strings.isNullOrEmpty(chaveOtp)) {
		throw new SmartCertException(Message.REQUISICAO_OAUTH_INVALIDA);
	}

	boolean otpValido = OTPOffLineUtil.getOTPWithKey(tokenAuth, chaveOtp)
			.equals(obterOtpOffline(codigoAcesso).toUpperCase());

	if (!otpValido) {
		throw new SmartCertException(Message.OTP_OFFLINE_INVALIDO);
	}

	authRequest.setCertificado(inst.getCertificado());
	authRequest.setDispositivo(inst.getDispositivo());

	authRequest.setTipoAutenticacao(TipoAutenticacao.WEB);
	authRequest.setDataPrimeiroFator(new Date());
	authRequest.setIpRespondente(nrc.getIp());
	authRequest.setStatus(AuthorizationRequest.Status.PRIMEIRO_FATOR_APRESENTADO);

	return Response.ok(RespostaAuthorizeBuilder.loginOtp(inst)).build();
}

